// MODELPACK-STACK-01: writes `index.generated.ts` from the pack folders, so a compiled binary embeds every pack
// (a static import is the only thing `bun build --compile` embeds). Run: `bun run src/packs/gen.ts` after adding a pack folder.
// `loader.test.ts` fails when the generated file is out of date.
import { readdirSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";

export function renderManifest(root: string): string {
  const dirs = readdirSync(root, { withFileTypes: true }).filter((d) => d.isDirectory() && existsSync(join(root, d.name, "model-pack.json"))).map((d) => d.name).sort();
  const lines: string[] = ["// GENERATED by src/packs/gen.ts. Do not edit by hand.", "export const PACK_SOURCES: ReadonlyArray<{ dir: string; pack: unknown; recipes: Readonly<Record<string, string>> }> = ["];
  const imports: string[] = [];
  dirs.forEach((dir, i) => {
    imports.push(`import pack${i} from "./${dir}/model-pack.json" with { type: "json" };`);
    const recipeDir = join(root, dir, "recipes");
    const recipes = existsSync(recipeDir) ? readdirSync(recipeDir).filter((f) => f.endsWith(".md")).sort() : [];
    recipes.forEach((f, j) => imports.push(`import recipe${i}_${j} from "./${dir}/recipes/${f}" with { type: "text" };`));
    lines.push(`  { dir: ${JSON.stringify(dir)}, pack: pack${i}, recipes: { ${recipes.map((f, j) => `${JSON.stringify("recipes/" + f)}: recipe${i}_${j}`).join(", ")} } },`);
  });
  lines.push("];", "");
  return [lines[0]!, ...imports, "", ...lines.slice(1)].join("\n");
}

if (import.meta.main) writeFileSync(join(import.meta.dir, "index.generated.ts"), renderManifest(import.meta.dir));
